import {platforms,step} from './physics.js';
const $=s=>document.querySelector(s),canvas=$('#game'),ctx=canvas.getContext('2d'),dialog=$('#panel'),comp=$('#companion'),cc=comp.getContext('2d');
const keys={left:false,right:false,jump:false},p={x:530,y:360,vx:0,vy:0,facing:1,grounded:true};
let room='main',near=null,last=0,time=0,walk=0,viewW=1100,camera=0,muted=true,audio,mouse={x:0,y:0},clickEnergy=0,visited=new Set();
const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;
const mainDoors=[{x:130,y:297,color:'#b6d5b0',title:'Sobre mim',sub:'A PESSOA POR TRÁS DO CÓDIGO',id:'about',icon:'◎'},{x:310,y:251,color:'#dfc38e',title:'Currículo',sub:'CAMINHO & EXPERIÊNCIA',id:'resume',icon:'≡'},{x:757,y:251,color:'#a4c8e1',title:'Projetos',sub:'IDEIAS QUE GANHARAM VIDA',id:'projects',icon:'⌘'},{x:970,y:297,color:'#d4b3ce',title:'Contato',sub:'O PRÓXIMO CAPÍTULO',id:'contact',icon:'↗'}];
const projectDoors=[{x:130,y:297,color:'#c8b7e5',title:'D Movies',sub:'EXPLORAR REPOSITÓRIO',id:'movies',icon:'▶'},{x:310,y:251,color:'#a4d7bf',title:'New Garden',sub:'EXPLORAR REPOSITÓRIO',id:'garden',icon:'✿'},{x:757,y:251,color:'#e4ca93',title:'Telecinese',sub:'LABORATÓRIO INTERATIVO',id:'lab',icon:'✧'},{x:970,y:297,color:'#a4c8e1',title:'Mais código',sub:'TODOS OS REPOSITÓRIOS',id:'github',icon:'⌘'}];
const gh='https://github.com/DiogoAlves2004', chips='<div class="chips">'+['.NET','Angular','DDD','PostgreSQL','Redis','Microservices','Microfrontends'].map(s=>`<span>${s}</span>`).join('')+'</div>';
const content={about:`<h2>Prazer, Diogo.</h2><p>Desenvolvedor de software. Gosto de transformar problemas em sistemas que fazem sentido — por dentro e por fora.</p><p>Trabalho com análise e desenvolvimento de sistemas web usando .NET, Angular, DDD e arquitetura em camadas. Minha experiência também passa por PostgreSQL, Redis e desenvolvimento mobile com React Native.</p>${chips}<div class="panel-links"><a href="${gh}" target="_blank" rel="noopener noreferrer">Explorar meu GitHub ↗</a><a class="secondary" href="https://www.linkedin.com/in/diogo-alves-26b83a221/" target="_blank" rel="noopener noreferrer">LinkedIn ↗</a></div>`,resume:`<h2>Meu caminho no código.</h2><p>Um resumo técnico baseado no meu perfil público. Para conhecer minha trajetória profissional completa, visite meu LinkedIn.</p><div class="timeline"><h3>Desenvolvimento de sistemas web</h3><p>.NET e Angular, com DDD e arquitetura em camadas.</p><h3>Arquitetura & dados</h3><p>Microsserviços .NET, microfrontends Angular com MFE, PostgreSQL e Redis.</p><h3>Outras experiências</h3><p>Desenvolvimento mobile com React Native.</p></div><div class="panel-links"><a href="curriculo.html" target="_blank" rel="noopener">Abrir currículo / salvar PDF ↗</a><a class="secondary" href="https://www.linkedin.com/in/diogo-alves-26b83a221/" target="_blank" rel="noopener noreferrer">Trajetória no LinkedIn ↗</a></div><p class="note">O currículo pode ser salvo como PDF pela opção Imprimir do navegador. Datas e empresas não foram adicionadas sem confirmação.</p>`,contact:`<h2>Vamos criar o próximo capítulo?</h2><p>Uma ideia, um desafio técnico ou uma conversa sobre tecnologia. A próxima porta pode começar aqui.</p><div class="panel-links"><a href="mailto:alvessilva524@gmail.com">Enviar um e-mail ↗</a><a class="secondary" href="https://www.linkedin.com/in/diogo-alves-26b83a221/" target="_blank" rel="noopener noreferrer">Conversar no LinkedIn ↗</a></div><p>alvessilva524@gmail.com</p>`,movies:`<h2>D Movies.</h2><p>Uma das portas do meu histórico de desenvolvimento. Explore o código e a documentação no repositório público.</p><div class="chips"><span>Projeto público</span><span>Código-fonte</span></div><div class="panel-links"><a href="${gh}/d-movies" target="_blank" rel="noopener noreferrer">Abrir repositório ↗</a></div>`,garden:`<h2>New Garden.</h2><p>Mais uma ideia que ganhou forma em código. O repositório público reúne os arquivos do projeto para explorar a implementação.</p><div class="chips"><span>Projeto público</span><span>Código-fonte</span></div><div class="panel-links"><a href="${gh}/new-garden" target="_blank" rel="noopener noreferrer">Abrir repositório ↗</a></div>`,github:`<h2>Continue explorando.</h2><p>Cada repositório conta um pedaço da minha jornada. Veja outros projetos, estudos e experimentos no meu GitHub.</p><div class="panel-links"><a href="${gh}?tab=repositories" target="_blank" rel="noopener noreferrer">Ver todos os repositórios ↗</a></div>`,lab:`<h2>O poder da intenção.</h2><p>Um experimento de comandos em linguagem natural: digite uma cor e veja a energia do personagem mudar.</p><div class="demo-box"><label for="command">Diga: “energia azul”, “verde”, “rosa” ou “dourada”.</label><form id="demo-form"><input id="command" placeholder="Quero uma energia azul" autocomplete="off" maxlength="160" required><button class="demo-button" type="submit">Manifestar energia ✧</button></form><output id="demo-output" aria-live="polite">Aguardando sua intenção…</output></div><p class="note">Demonstração local com interpretação por regras. Não utiliza um modelo de IA nem envia dados. Este espaço está preparado para receber um agente real.</p>`};
let energy='#d9eea1',restoreFocus=null;
function sound(f=500){if(muted)return;audio??=new (window.AudioContext||window.webkitAudioContext)();audio.resume();const o=audio.createOscillator(),g=audio.createGain();o.type='sine';o.frequency.setValueAtTime(f,audio.currentTime);o.frequency.exponentialRampToValueAtTime(f*1.5,audio.currentTime+.12);g.gain.setValueAtTime(.035,audio.currentTime);g.gain.exponentialRampToValueAtTime(.001,audio.currentTime+.2);o.connect(g).connect(audio.destination);o.start();o.stop(audio.currentTime+.2);}
function openPanel(id){if(id==='projects'){changeRoom('projects');return;}if(!content[id])return;keys.left=keys.right=keys.jump=false;restoreFocus=document.activeElement;$('#panel-content').innerHTML=content[id];$('#panel-category').textContent=room==='projects'?'DENTRO DE UM PROJETO':'UMA PARTE DA MINHA HISTÓRIA';if(!dialog.open)dialog.showModal();visited.add(id);sound(580);if(id==='lab')$('#demo-form').addEventListener('submit',e=>{e.preventDefault();const v=$('#command').value.toLowerCase();const colors=[[/azul|blue/,'#8dccec','azul'],[/verde|green/,'#b7e291','verde'],[/rosa|pink|roxa/,'#e8a3da','rosa'],[/dourad|amarel|gold/,'#eed18b','dourada']];const found=colors.find(c=>c[0].test(v));if(found){energy=found[1];clickEnergy=1;$('#demo-output').textContent=`Intenção reconhecida. Energia ${found[2]} ativada! Mova o cursor para guiar o personagem.`;sound(720);}else $('#demo-output').textContent='Ainda não reconheci essa cor. Tente azul, verde, rosa ou dourada.';});}
function closePanel(){dialog.close();sound(320);if(restoreFocus?.isConnected)restoreFocus.focus();}
function changeRoom(next){room=next;p.x=530;p.y=360;p.vx=p.vy=0;keys.left=keys.right=keys.jump=false;near=null;$('#room-label').textContent=next==='projects'?'LOBBY DOS PROJETOS':'LOBBY PRINCIPAL';$('#back-room').hidden=next!=='projects';$('#scene-hint').textContent=next==='projects'?'Cada projeto abre uma nova possibilidade.':'Seu próximo passo pode abrir uma nova ideia.';document.body.classList.remove('room-transition');void canvas.offsetWidth;document.body.classList.add('room-transition');sound(420);canvas.focus({preventScroll:true});}
document.querySelectorAll('[data-open]').forEach(b=>b.onclick=()=>openPanel(b.dataset.open));document.querySelectorAll('[data-room]').forEach(b=>b.onclick=()=>changeRoom(b.dataset.room));$('.brand').onclick=e=>{e.preventDefault();changeRoom('main');};$('#close-panel').onclick=closePanel;dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closePanel();}});dialog.addEventListener('close',()=>{keys.left=keys.right=keys.jump=false;});$('#back-room').onclick=()=>changeRoom('main');$('#year').textContent=new Date().getFullYear();
function enter(){if(near)openPanel(near.id);}$('#enter-door').onclick=enter;$('#touch-enter').onclick=enter;
$('#sound').onclick=()=>{muted=!muted;$('#sound').setAttribute('aria-pressed',String(!muted));$('#sound span').textContent=muted?'Som desligado':'Som ligado';sound(500);};
function key(e,down){if(dialog.open)return;const map={ArrowLeft:'left',a:'left',A:'left',ArrowRight:'right',d:'right',D:'right',' ':'jump',ArrowUp:'jump',w:'jump',W:'jump'};if(map[e.key]){e.preventDefault();keys[map[e.key]]=down;}if(down&&!e.repeat&&(e.key==='e'||e.key==='E'||e.key==='Enter'))enter();if(down&&e.key==='Escape'&&room==='projects')changeRoom('main');}
window.addEventListener('keydown',e=>key(e,true));window.addEventListener('keyup',e=>key(e,false));window.addEventListener('blur',()=>{keys.left=keys.right=keys.jump=false;});document.addEventListener('visibilitychange',()=>{keys.left=keys.right=keys.jump=false;last=0;});
document.querySelectorAll('[data-control]').forEach(b=>{b.addEventListener('pointerdown',e=>{e.preventDefault();b.setPointerCapture(e.pointerId);keys[b.dataset.control]=true;});['pointerup','pointercancel','lostpointercapture'].forEach(ev=>b.addEventListener(ev,()=>keys[b.dataset.control]=false));});
window.addEventListener('pointermove',e=>{mouse.x=e.clientX;mouse.y=e.clientY;});dialog.addEventListener('pointerdown',()=>{clickEnergy=1;sound(650);});
canvas.addEventListener('click',e=>{const r=canvas.getBoundingClientRect(),x=(e.clientX-r.left)/r.width*viewW+camera,y=(e.clientY-r.top)/r.height*430;const d=(room==='main'?mainDoors:projectDoors).find(d=>Math.abs(x-d.x)<55&&y>d.y-130&&y<d.y+8);if(d){p.x=d.x;p.y=d.y;p.vx=p.vy=0;openPanel(d.id);}canvas.focus({preventScroll:true});});
function fit(){const dpr=Math.min(devicePixelRatio||1,2);viewW=innerWidth<700?550:1100;canvas.width=Math.round(viewW*dpr);canvas.height=Math.round(430*dpr);comp.width=300;comp.height=240;}window.addEventListener('resize',fit);fit();
function round(c,x,y,w,h,r,fill,stroke){c.beginPath();c.roundRect(x,y,w,h,r);if(fill){c.fillStyle=fill;c.fill();}if(stroke){c.strokeStyle=stroke;c.lineWidth=1;c.stroke();}}
function line(c,x,y,x2,y2,color,width=1){c.beginPath();c.moveTo(x,y);c.lineTo(x2,y2);c.strokeStyle=color;c.lineWidth=width;c.stroke();}
function text(c,str,x,y,size=12,color='#d8e0cc',align='center'){c.font=`${size}px "DM Sans",sans-serif`;c.fillStyle=color;c.textAlign=align;c.fillText(str,x,y);}
function plant(x,y,s=1){ctx.save();ctx.translate(x,y);ctx.scale(s,s);for(let i=0;i<6;i++){const a=(i-2.5)*.4;ctx.save();ctx.rotate(a+Math.sin(time*.7+i)*.035);ctx.beginPath();ctx.ellipse(0,-28,5,23,0,0,Math.PI*2);ctx.fillStyle=i%2?'#82955e':'#566e4b';ctx.fill();ctx.restore();}round(ctx,-12,-6,24,24,[2,2,8,8],'#786b50');line(ctx,-13,-6,13,-6,'#ad9770',3);ctx.restore();}
function character(c,x,y,scale=1,psychic=false){c.save();c.translate(x,y);c.scale(scale,scale);const moving=!psychic&&Math.abs(p.vx)>12,bob=reduced?0:Math.sin(time*(moving?13:2.4))*(moving?1.5:1.1),swing=moving?Math.sin(walk)*.62:0;c.translate(0,bob);c.lineCap='round';c.fillStyle='#0003';c.beginPath();c.ellipse(0,1,18,4,0,0,Math.PI*2);c.fill();for(let i of [-1,1]){c.save();c.translate(i*7,-14);c.rotate(swing*i);round(c,-4,0,8,15,4,'#253c36');round(c,-5,10,12,6,3,'#d5d8bd');c.restore();}round(c,-15,-43,30,30,[12,12,7,7],'#cbdba5');round(c,-11,-40,22,14,5,'#b9ce8d');line(c,-2,-36,-2,-22,'#8b9d70');round(c,-17,-63,34,28,12,'#ebc6a3');c.fillStyle='#253934';c.beginPath();c.moveTo(-17,-46);c.bezierCurveTo(-29,-74,7,-83,20,-63);c.lineTo(19,-48);c.lineTo(10,-59);c.quadraticCurveTo(-3,-51,-17,-54);c.fill();let eye=psychic?Math.max(-3,Math.min(3,(mouse.x-innerWidth/2)/150)):p.facing*2;for(let i of [-1,1])round(c,i*6+eye-1,-49,2.5,4,1,'#283b35');line(c,-2,-40,3,-40,'#ac7b63',1.5);for(let i of [-1,1]){const handX=psychic?i*28:i*(19+Math.sin(walk)*2),handY=psychic?-49-Math.sin(time*3+i)*3:-24-swing*i*9;line(c,i*12,-35,handX,handY,'#bbce91',9);round(c,handX-4,handY-3,8,8,4,'#ebc6a3');if(psychic){c.shadowBlur=18;c.shadowColor=energy;c.strokeStyle=energy;c.lineWidth=1;c.beginPath();c.ellipse(handX,handY-6,12+clickEnergy*8,5,time*.4*i,0,Math.PI*2);c.stroke();c.shadowBlur=0;}}c.restore();}
function drawDoor(d){const active=near?.id===d.id;ctx.save();ctx.translate(d.x,d.y);ctx.shadowColor=d.color;ctx.shadowBlur=active?28:9;round(ctx,-38,-113,76,113,[37,37,3,3],'#182724',d.color);ctx.shadowBlur=0;const g=ctx.createLinearGradient(-27,-100,27,0);g.addColorStop(0,active?d.color+'80':d.color+'25');g.addColorStop(1,d.color+'08');round(ctx,-30,-105,60,105,[30,30,1,1],g,d.color+'55');ctx.save();ctx.beginPath();ctx.roundRect(-30,-105,60,105,[30,30,1,1]);ctx.clip();for(let i=0;i<5;i++){let yy=-((time*(active?28:8)+i*25)%120);line(ctx,-30,yy,30,yy,d.color+'13');}ctx.restore();text(ctx,d.icon,0,-55,27,d.color);round(ctx,19,-37,3,7,2,d.color);line(ctx,-43,0,43,0,d.color,3);text(ctx,d.title,0,-133,15,d.color);text(ctx,d.sub,0,23,6.2,'#8da18c');if(visited.has(d.id))text(ctx,'✓',29,-95,10,d.color);if(active){round(ctx,-19,-164,38,19,5,'#d9eea1');text(ctx,'E  ↵',0,-151,10,'#233520');}ctx.restore();}
function drawScene(){const dpr=Math.min(devicePixelRatio||1,2);ctx.setTransform(dpr,0,0,dpr,0,0);ctx.clearRect(0,0,viewW,430);camera=viewW<1100?Math.max(0,Math.min(1100-viewW,p.x-viewW/2)):0;ctx.save();ctx.translate(-camera,0);const bg=ctx.createLinearGradient(0,0,0,430);bg.addColorStop(0,'#21332f');bg.addColorStop(.7,'#1d2d29');bg.addColorStop(1,'#111e1a');ctx.fillStyle=bg;ctx.fillRect(0,0,1100,430);
// Architectural backdrop, high windows and soft light.
for(let x=70;x<1100;x+=160){round(ctx,x,24,105,175,[48,48,1,1],'#172a26','#374b3e');const glow=ctx.createLinearGradient(x,30,x,195);glow.addColorStop(0,'#a4b68c22');glow.addColorStop(1,'#a4b68c03');round(ctx,x+6,30,93,163,[44,44,0,0],glow);line(ctx,x+52,30,x+52,195,'#42523e');line(ctx,x+6,117,x+99,117,'#42523e');ctx.fillStyle='#bacd8110';ctx.beginPath();ctx.moveTo(x+8,32);ctx.lineTo(x+99,32);ctx.lineTo(x+160,360);ctx.lineTo(x-45,360);ctx.fill();}for(let i=0;i<32;i++){const x=(i*83.3+Math.sin(time*.15+i)*10)%1100,y=(i*43.1-time*(reduced?0:4)+450)%340;ctx.fillStyle=`rgba(211,229,172,${.12+Math.sin(time+i)*.08})`;ctx.beginPath();ctx.arc(x,y,i%3===0?1.6:.8,0,Math.PI*2);ctx.fill();}
// Hanging lights and cables.
for(const x of [210,550,885]){line(ctx,x,0,x,38,'#53634a');round(ctx,x-22,37,44,8,4,'#6b7857');ctx.shadowColor='#e1dfa1';ctx.shadowBlur=25;round(ctx,x-16,44,32,3,2,'#e1dfa1');ctx.shadowBlur=0;}text(ctx,room==='main'?'THE CURIOUS LAB':'THE PROJECT ARCHIVE',550,90,9,'#7e9475');text(ctx,room==='main'?'ideias em construção constante':'abra uma porta, explore o código',550,108,7,'#617b62');
// Shelves, server and desk.
round(ctx,455,147,184,8,2,'#59634a');for(let i=0;i<9;i++)round(ctx,466+i*13,121+(i%3)*4,8,26-(i%3)*4,1,['#84926d','#b6ad7c','#6a8c7c'][i%3]);plant(620,136,.45);round(ctx,486,206,115,6,2,'#8e8763');line(ctx,495,212,490,286,'#5d6e53',4);line(ctx,591,212,597,286,'#5d6e53',4);round(ctx,517,166,55,33,4,'#101f1c','#7a8e69');round(ctx,522,171,45,23,2,'#33574a');text(ctx,'> hello, world_',544,185,5,'#c9e2a3');line(ctx,544,199,544,205,'#76866a',4);round(ctx,580,191,12,15,[2,2,5,5],'#bdad7b');
round(ctx,32,310,32,50,3,'#344538','#60744f');for(let i=0;i<3;i++){round(ctx,37,317+i*12,22,8,2,'#182a21');ctx.fillStyle=i===1?'#d3c18b':'#b3ce83';ctx.fillRect(40,320+i*12,3,2);}plant(1053,343,.85);plant(419,344,.7);plant(854,344,.6);
for(const plat of platforms){if(plat.y===360)continue;round(ctx,plat.x,plat.y,plat.w,12,3,'#57634a','#788465');ctx.fillStyle='#273a2e';ctx.fillRect(plat.x+8,plat.y+12,plat.w-16,9);line(ctx,plat.x+4,plat.y+1,plat.x+plat.w-4,plat.y+1,'#adb88c',2);for(let i=0;i<3;i++){const x=plat.x+20+i*43;line(ctx,x,plat.y+23,x+8,plat.y+32,'#4b5b42',2);}}
// Little stepping stones make the platform layout readable.
for(const s of [{x:212,y:328},{x:652,y:310},{x:867,y:326}])round(ctx,s.x-17,s.y,34,8,3,'#65704e','#93a074');
(room==='main'?mainDoors:projectDoors).forEach(drawDoor);
// Ground section and grass.
ctx.fillStyle='#31432f';ctx.fillRect(0,360,1100,70);ctx.fillStyle='#71825a';ctx.fillRect(0,360,1100,4);ctx.fillStyle='#1e3024';ctx.fillRect(0,374,1100,56);for(let x=0;x<1100;x+=25){line(ctx,x,364,x+8,361,'#a5b87d',1);if(x%50===0){line(ctx,x,360,x-3,352,'#849e64');line(ctx,x,360,x+4,354,'#849e64');}round(ctx,x+5,390+(x%3)*8,7,2,1,'#44553a');}line(ctx,0,428,1100,428,'#425a37',2);
// Small floating companion drone.
const by=315+(reduced?0:Math.sin(time*2.5)*4);ctx.shadowColor='#cee39e';ctx.shadowBlur=12;round(ctx,592,by,22,16,7,'#a9bf83');ctx.shadowBlur=0;round(ctx,596,by+4,14,7,3,'#1d3d31');round(ctx,599,by+6,3,2,1,'#d6eeaa');round(ctx,605,by+6,3,2,1,'#d6eeaa');line(ctx,603,by,603,by-7,'#a9bf83');text(ctx,'✧',603,by-8,9,'#d9eea1');
character(ctx,p.x,p.y,1);if(Math.abs(p.vx)>30&&p.grounded&&!reduced){for(let i=0;i<3;i++){ctx.fillStyle='#b3c88b33';ctx.beginPath();ctx.arc(p.x-p.facing*(16+i*10),p.y-2,2+i*.5,0,Math.PI*2);ctx.fill();}}ctx.restore();}
function drawCompanion(){cc.setTransform(2,0,0,2,0,0);cc.clearRect(0,0,150,120);if(!dialog.open)return;character(cc,73,108,1.15,true);const rect=comp.getBoundingClientRect(),targetX=Math.max(4,Math.min(146,(mouse.x-rect.left)/rect.width*150)),targetY=Math.max(3,Math.min(50,(mouse.y-rect.top)/rect.height*120));cc.strokeStyle=energy+'55';cc.lineWidth=.7;for(let i of [-1,1]){cc.beginPath();cc.moveTo(73+i*32,45);cc.quadraticCurveTo(73+i*44,10,targetX,targetY);cc.stroke();}cc.fillStyle=energy;cc.shadowBlur=15;cc.shadowColor=energy;cc.beginPath();cc.arc(targetX,targetY,2+clickEnergy*3,0,Math.PI*2);cc.fill();cc.shadowBlur=0;}
function frame(now){const dt=Math.min((now-last)/1000||1/60,.025);last=now;time+=dt;clickEnergy=Math.max(0,clickEnergy-dt*2);if(!dialog.open){const before=p.grounded;step(p,keys,dt);walk+=Math.abs(p.vx)*dt*.07;if(before&&!p.grounded&&p.vy<0)sound(350);const old=near;near=(room==='main'?mainDoors:projectDoors).find(d=>Math.abs(p.x-d.x)<52&&Math.abs(p.y-d.y)<25)||null;if(old!==near){$('#enter-door').hidden=!near;if(near)$('#enter-door').innerHTML=`Entrar: ${near.title} <kbd>E</kbd>`;}}drawScene();drawCompanion();requestAnimationFrame(frame);}requestAnimationFrame(frame);
